    "台東": "타이둥",
    "台鐵 · 高鐵 · 阿里山林鐵（真實時刻）｜ 捷運 · 輕軌（官方時刻表，主要路網看板校正）": "대만철도 · 고속철도 · 아리산 삼림철도(시간표 기준) | MRT · 경전철(공식 시간표, 주요 노선은 실시간 도착 정보로 보정)",
    "全台鐵道一次看 — 台鐵、高鐵、阿里山林鐵與各捷運／輕軌皆依當日時刻表同一時間軸運行（台鐵套即時誤點；主要捷運營運時段依官方到站看板校正）。": "대만철도, 고속철도, 아리산 삼림철도와 각 MRT · 경전철을 하나의 시간축에서 보세요. 대만철도는 실시간 지연을 반영하고, 지원되는 MRT 노선은 공식 도착 정보로 보정해요.",
    "台鐵環島幹線與各支線依當日真實時刻表運行（回到現在時刻自動套用即時誤點），阿里山林鐵同框（依官方公告時刻表，無即時資訊）— 點列車跟隨、點車站看班次。": "대만철도 본선과 지선은 오늘 시간표에 따라 운행하며, 현재 시간에는 실시간 지연을 반영해요. 아리산 삼림철도는 공식 시간표를 사용하며 실시간 정보는 없어요. 열차를 누르면 따라가고, 역을 누르면 도착 정보를 볼 수 있어요.",
    "台北捷運、桃園機捷、新北捷運（環狀・淡海・安坑・三鶯）、台中捷運與高雄捷運（含輕軌）同框運行，營運時段依官方即時資訊校正（文湖線、三鶯線與台中捷運為班距推算）— 可在上方勾選要同時顯示的系統。": "타이베이, 타오위안, 신베이(순환 · 단하이 · 안컹 · 싼잉), 타이중, 가오슝의 MRT와 경전철을 함께 볼 수 있어요. 운행 중에는 지원 노선을 공식 실시간 정보로 보정하며, 원후선 · 싼잉선 · 타이중 MRT는 배차간격으로 추정해요. 위에서 표시할 시스템을 선택하세요.",
    "列車依當日時刻表運行，回到現在時刻（1×）會自動套用台鐵即時誤點修正 — 點列車跟隨、點車站看班次，或按地圖角落「探」看今日亮點列車。": "열차는 오늘 시간표에 따라 운행해요. 현재 시간(1×)에는 대만철도 실시간 지연이 자동 반영돼요. 열차를 눌러 따라가거나 역을 눌러 도착 정보를 보세요. 지도 모서리의 탐색 버튼에서 오늘의 특별한 열차도 찾아보세요.",
    "高鐵列車依當日真實時刻表沿西部走廊南北奔馳（南港－左營）— 點列車跟隨、點車站看班次。": "고속철도 열차가 오늘 시간표에 따라 난강에서 쭤잉까지 서부를 달려요. 열차를 누르면 따라가고, 역을 누르면 도착 정보를 볼 수 있어요.",
    "阿里山林業鐵路從嘉義平原一路盤旋上山，途中經過獨立山螺旋與第一分道的之字形折返——列車依官方公告時刻表運行（本線無即時資訊，且常因天候或維修停駛）。祝山線觀日列車每天隨日出調整、前一日 16:30 才公告，畫面依官方日出時間表推算並標示「推算」，實際請以林鐵官網為準。": "아리산 삼림철도는 자이 평야에서 출발해 두리산 나선 구간과 제1분기점의 지그재그 구간을 지나 산을 올라가요. 공식 시간표를 사용하며 실시간 정보는 없고, 날씨나 정비로 운행이 취소될 수 있어요. 주산선 일출열차는 전날 16:30에 시간이 공지돼요. 지도에서는 공식 일출 시간표로 추정해 표시하므로, 실제 시간은 삼림철도 공식 홈페이지에서 확인하세요.",
    "各線列車依當日實際時刻表在城市裡穿梭，營運時段依官方到站看板即時校正（環狀線依新北捷運官方列車動態；文湖線為班距推算）— 拖曳、縮放看看。": "각 노선은 오늘 시간표에 따라 운행해요. 지원 노선은 운행 시간에 공식 도착 정보로 보정하며, 순환선은 신베이 MRT의 공식 열차 위치를, 원후선은 배차간격에 따른 추정을 사용해요. 지도를 드래그하거나 확대해 보세요.",
    "機場捷運直達車與普通車依當日實際時刻表連結雙北與桃園機場，營運時段依官方到站看板即時校正 — 拖曳、縮放看看。": "공항 MRT 급행열차와 보통열차가 오늘 시간표에 따라 타이베이 · 신베이와 타오위안 공항을 연결해요. 운행 중에는 공식 도착 정보로 보정해요. 지도를 드래그하거나 확대해 보세요.",
    "淡海輕軌綠山線與藍海線依官方當日時刻表在淡水穿梭，營運時段依官方列車動態即時校正 — 拖曳、縮放看看。": "단하이 경전철의 뤼산선과 란하이선은 오늘 공식 시간표에 따라 운행하며, 운행 중에는 공식 열차 위치로 보정해요. 지도를 드래그하거나 확대해 보세요.",
    "安坑輕軌依官方當日時刻表沿安康路串起新店丘陵，營運時段依官方列車動態即時校正 — 拖曳、縮放看看。": "안컹 경전철은 오늘 공식 시간표에 따라 신뎬 구릉 지역을 연결하며, 운행 중에는 공식 열차 위치로 보정해요. 지도를 드래그하거나 확대해 보세요.",
    "紅橘兩線與環狀輕軌依當日實際時刻表在港都穿梭，營運時段依官方到站看板即時校正 — 拖曳、縮放看看。": "가오슝의 레드라인 · 오렌지라인과 순환 경전철은 오늘 시간표에 따라 운행하며, 운행 중에는 공식 도착 정보로 보정해요. 지도를 드래그하거나 확대해 보세요.",
