    "衛星底圖": "위성 지도",
    "App 進階定位與 Live Activity": "앱 고급 위치 기능 및 실시간 현황",
    "創始會員徽章": "창립 회원 배지",
    "管理訂閱": "구독 관리",
    "恢復購買": "구매 복원",
    "正在讀取方案與訂閱資格…": "요금제 및 구독 상태 확인 중…",
    "目前請在軌島 App 內訂閱；訂閱後同一個軌島帳號在網站也會自動生效。": "현재 구독은 Rail Island 앱에서 진행해 주세요. 구독 후 같은 계정으로 웹에서도 자동 활성화돼요.",
    "最划算": "가장 경제적",
    "年訂閱": "연간 구독",
    "月訂閱": "월간 구독",
    "已訂閱？恢復購買": "이미 구독 중이신가요? 구매 복원",
    "目前無法取得訂閱方案，請稍後再試。": "지금은 구독 요금제를 불러올 수 없어요. 잠시 후 다시 시도해 주세요.",
    "隱私權政策": "개인정보 처리방침",
    "使用條款": "이용약관",
