    "假日": "휴일",
    "懸賞板暫時讀不到，等一下再試一次": "미션 게시판을 지금 불러올 수 없어요. 잠시 후 다시 시도하세요.",
    "目前沒有待校正的項目——全部收滿了。": "현재 보정할 항목이 없어요. 모두 수집되었어요.",
    "這些項目還沒有實測資料。用 App 才能接下來錄——網頁可以先看看有哪些。": "아직 실측 자료가 없는 항목이에요. 앱에서 미션을 받고 기록할 수 있으며 웹에서는 목록을 볼 수 있어요.",
    "{first}等 {n} 站　停站": "{first} 등 {n}개 역 · 정차",
    "{first}　停站": "{first} · 정차",
