    "已接下・看說明": "참여 중 · 안내 보기",
    "接下停站": "정차 미션 참여",
    "接下這段": "이 구간 참여",
    "GPS 校正旅程需要用 App。網頁可以看懸賞板與自己的成果": "GPS 보정 여정은 앱이 필요해요. 웹에서는 미션과 내 결과를 볼 수 있어요.",
    "（示範）找不到這張卡": "(데모) 이 카드를 찾을 수 없어요",
    "（示範）這台裝置存不下來，示範資料無法保留": "(데모) 기기에 저장할 수 없어 데모 기록을 유지할 수 없어요",
    "接不下來——{reason}": "참여 불가 — {reason}",
