    "春節": "춘절",
    "和平紀念日": "평화기념일",
    "兒童節與清明": "어린이날 · 청명절",
    "中秋": "중추절",
    "國慶": "국경절",
    "光復節": "대만 광복절",
    "行憲紀念日": "헌법기념일",
    "Android 雙看板小工具字放大、依卡片高度多列幾班；設定頁通行證文字修正": "Android 철도 + MRT 전광판 위젯의 글자를 키우고 카드 높이에 따라 더 많은 열차를 표시해요. 설정의 패스 설명도 수정했어요.",
    "高雄輕軌的五節車身重新對齊，近看不再一節高、一節低": "가오슝 경전철 5개 차체의 높이를 맞춰 가까이에서 번갈아 높고 낮게 보이지 않아요",
    "平溪、深澳、集集、內灣線的列車改照 DR1000 柴油客車加減速，列車卡也改顯示 DR1000 介紹": "핑시 · 선아오 · 지지 · 네이완선에 DR1000 디젤 동차의 가감속을 적용하고 열차 카드 소개도 DR1000으로 바꿨어요",
    "台鐵列車在地圖上不再跑得比車種極速還快，新馬急彎與立體地圖都修正了，站牌時刻不變": "대만철도 열차가 차종 최고속도를 넘지 않도록 신마 급곡선과 3D 지도를 수정했어요. 역 시간은 유지해요.",
    "暗色模式下，附近車站、平交道、糖鐵與儲存地點卡的關閉鈕與「存」看得見了": "다크 모드에서 주변 역 · 건널목 · 사탕수수 철도 · 장소 카드의 닫기와 저장 버튼이 잘 보여요",
    "暗色主題下「面板半透明」開關恢復作用；半透明時看板倒數、預計到站與「在 Google 地圖開啟」等藍字加深，疊在衛星影像上也看得清楚": "다크 모드에서 반투명 패널 스위치가 다시 작동해요. 반투명일 때 도착 안내의 카운트다운 · 도착 예상 · Google Maps에서 열기 등 파란 글자를 진하게 해 위성 영상 위에서도 잘 보여요.",
    "英日文介面補上漏翻的按鈕、路線名、公告與提示，切換語言不再殘留前一種語言；車站看板太長的字改成兩行，不再被切掉；iOS 定位權限說明改用中文": "영어 · 일본어 화면에서 번역이 빠진 버튼 · 노선 이름 · 공지 · 알림을 보완하고, 언어를 바꾼 뒤 이전 언어가 남지 않게 했어요. 도착 안내의 긴 글자는 두 줄로 표시해 잘리지 않아요. iOS 위치 권한 안내도 중국어로 바꿨어요.",
    "非營運時段": "운행 시간 아님",
    "正常營運": "정상 운행",
    "軌島 Google Play 新版 有什麼新的": "Rail Island Google Play 새 버전의 새로운 기능",
    "從台鐵發車看板或鐵路＋捷運雙看板點進軌島時，會回到正確的鐵路地圖與車站；臺北車站不會再被同名的捷運站截走": "대만철도 출발 전광판이나 철도 + MRT 전광판에서 Rail Island를 열면 올바른 철도 지도와 역으로 이동해요. 타이베이역이 같은 이름의 MRT 역으로 잘못 열리지 않아요.",
    "App 有新版時，頂端的更新提示不再蓋住「觀看」按鈕": "앱 업데이트 알림이 상단 보기 버튼을 가리지 않아요",
    "台鐵後車待避與對向交會都保留安全間隔，同一條軌道上互相穿過的情況再減少": "뒤 열차 대피와 반대 방향 교행에 안전 간격을 유지해 같은 선로 관통을 더 줄였어요",
    "再按一次就關閉，面板回到原本的樣子": "다시 누르면 닫히고 패널이 원래 모습으로 돌아와요",
    "iPhone／iPad 底部速度膠囊淡出後點一下就會展開，不用再點兩下、也不會誤觸暫停": "iPhone / iPad 아래 속도 캡슐이 흐려진 뒤 한 번만 눌러도 펼쳐지고 일시정지가 잘못 눌리지 않아요",
