    "可在網址列旁圖示→網站設定→位置 允許": "주소창 옆 아이콘 → 사이트 설정 → 위치를 허용해 주세요",
    "可在網址列鎖頭圖示→位置 允許": "주소창 자물쇠 아이콘 → 위치를 허용해 주세요",
    "無法自動定位，已改用「釘」：在地圖上點你的位置就能看附近火車。（{note}）": "위치를 자동으로 확인하지 못해 핀 모드로 바꿨어요. 지도에서 내 위치를 눌러 주변 열차를 보세요. ({note})",
    "訂閱到期前會依商店規則自動續訂扣款；你可以隨時在 App Store／Google Play 或帳號的訂閱設定中取消，取消後於當期結束時停止續訂。": "스토어 규정에 따라 구독 기간이 끝나기 전에 자동 갱신 결제돼요. App Store · Google Play 또는 계정의 구독 설정에서 언제든 취소할 수 있으며, 취소하면 현재 기간 종료 시 갱신이 중단돼요.",
