    "影響路線：": "영향받는 노선: ",
    "、": ", ",
    "通阻公告": "운행 알림",
    "來源：TDX 營運通阻／狀態公告（每 5 分鐘更新）· 動畫依當日時刻表推演，台鐵誤點已逐車套用、部分捷運營運時段依官方即時資訊校正；但停駛、取消或加開的班次與臨時班距調整不會反映——畫面上列車仍可能照表出現，實際運行以官方公告為準": "출처: TDX 운행 알림(5분마다 업데이트). 애니메이션은 오늘 시간표를 따르며 대만철도 지연과 지원 MRT의 공식 실시간 보정을 반영해요. 운행 취소 · 임시열차 · 배차간격 임시 변경은 반영되지 않을 수 있어, 지도에 예정대로 열차가 나타날 수 있어요. 실제 운행은 운영사 공식 공지를 확인하세요.",
    "⚠ 本路線有{system}通阻公告，班次可能停駛——以官方公告為準": "⚠ {system}에서 이 노선의 운행 알림을 발표했어요. 운행이 취소될 수 있으니 공식 공지를 확인하세요.",
    "設定末班車提醒": "막차 알림 설정",
    "跟隨往 {station} 的班次": "{station} 방면 열차 따라가기",
    "（部分路線為班距推算）": "(일부 노선은 배차간격으로 추정)",
    "目前誤點 {n} 分": "현재 {n}분 지연",
    "📊 資料來源與授權": "📊 데이터 출처 및 라이선스",
    "🔒 隱私與服務條款": "🔒 개인정보 및 서비스 약관",
    "資料源連線狀態頁": "데이터 출처 연결 상태",
    "⭐ 開源專案，歡迎貢獻": "⭐ 오픈소스 프로젝트 · 기여를 환영해요",
    "隱私": "개인정보",
    "條款": "약관",
    "資料來源：各營運機構官方時刻表與交通部 TDX。台鐵套用即時誤點，支援的捷運路網依官方即時資訊校正；停駛、取消、加開與臨時班距調整可能未反映。": "출처: 각 운영사의 공식 시간표와 대만 TDX. 대만철도 실시간 지연과 지원 MRT의 실시간 보정을 반영해요. 운행 취소 · 임시열차 · 배차간격 임시 변경은 반영되지 않을 수 있어요.",
    "資料來源：交通部 TDX 阿里山林業鐵路定期時刻表。本線無即時位置或誤點資料，且可能因天候或維修停駛；祝山觀日列車為推算，請以林鐵當日公告為準。": "출처: TDX 아리산 삼림철도 정기 시간표. 실시간 위치 및 지연 정보가 없으며 날씨나 정비로 운행이 취소될 수 있어요. 주산 일출열차는 추정치이므로 당일 공식 공지를 확인하세요.",
    "資料來源：台鐵官方每日時刻表與交通部 TDX 即時誤點。動畫依時刻表推演並在目前時刻套用誤點；停駛、取消或加開班次可能未反映。": "출처: 대만철도 공식 일일 시간표 및 TDX 실시간 지연. 시간표를 바탕으로 현재 시간의 지연을 반영해요. 운행 취소나 임시열차는 반영되지 않을 수 있어요.",
    "資料來源：交通部 TDX 高鐵每日時刻表。動畫依當日真實時刻表推演；營運異常請以高鐵官方公告為準。": "출처: TDX 고속철도 일일 시간표. 오늘 실제 시간표를 바탕으로 표시하며, 운행 이상은 고속철도 공식 공지를 확인하세요.",
    "資料來源：各捷運公司與交通部 TDX 官方時刻表。支援的路網在營運時段依官方即時資訊校正；部分路線無逐班時刻，以官方班距推算。": "출처: 각 MRT 운영사 및 TDX 공식 시간표. 지원 노선은 운행 중 공식 실시간 정보로 보정하며, 열차별 시간표가 없는 노선은 공식 배차간격으로 추정해요.",
    "這個檢視沒有車站": "이 화면에는 역이 없어요",
    "切換到含車站的檢視再定位": "역이 있는 화면으로 바꾼 뒤 위치를 확인해 주세요",
    "附近找不到車站": "주변 역을 찾을 수 없어요",
