    "半徑內無，顯示最近 {n} 站": "반경 안에 역이 없어 가까운 {n}개 역을 표시해요",
    "今天已蓋 ✓": "오늘 스탬프 완료 ✓",
    "蓋章 · 第 {n} 次": "스탬프 · {n}번째 방문",
