    "這是外部災害示警，不代表列車已停駛；軌島已加強重查台鐵、高鐵與捷運的官方營運公告{stale}。列車是否停駛請以各營運單位公告為準。來源：NCDR 民生示警公開資料平台。": "외부 재난 경보이며 열차 운행 중단을 뜻하지 않아요. Rail Island는 대만철도 · 고속철도 · MRT의 공식 운행 공지를 더 자주 확인하고 있어요{stale}. 실제 운행 여부는 각 운영사의 공식 공지를 확인하세요. 출처: NCDR 공공 경보 플랫폼.",
    "影響路線：{routes}": "영향받는 노선: {routes}",
    "來源：TDX 營運通阻／狀態公告（平時每 5 分鐘；災害示警生效時加強重查）": "출처: TDX 운행 · 상태 공지(평소 5분마다, 재난 경보 발효 시 더 자주 확인)",
    "；災害觸發來源：NCDR 生效中示警": "; 재난 감지 출처: 발효 중인 NCDR 경보",
    "動畫依當日時刻表推演，台鐵誤點已逐車套用、部分捷運營運時段依官方即時資訊校正；但停駛、取消或加開的班次與臨時班距調整不會反映——畫面上列車仍可能照表出現，實際運行以官方公告為準": "애니메이션은 오늘 시간표를 따르며, 대만철도 열차별 지연과 지원 MRT의 공식 실시간 보정을 반영해요. 운행 취소 · 임시열차 · 배차간격 임시 변경은 반영되지 않을 수 있어 지도에 예정대로 열차가 나타날 수 있어요. 실제 운행은 공식 공지를 확인하세요.",
    "本路線有{system}通阻公告，班次可能停駛——以官方公告為準": "이 노선에 {system} 운행 알림이 있어 운행이 취소될 수 있어요. 공식 공지를 확인하세요.",
    "停駛": "운행 취소",
