    "可能是本站服務或你目前的網路連線，不一定是官方端。": "운영사 외에 Rail Island 서비스나 현재 인터넷 연결이 원인일 수도 있어요. ",
    "以下倒數與地圖上的列車位置都是依各站之間的固定行車時間推估的，可能與實際不符，也可能整段空著。": "아래 카운트다운과 지도 위 열차 위치는 역 사이의 고정 운행 시간으로 추정해요. 실제와 다르거나 구간 전체가 비어 있을 수 있어요.",
    "這不代表列車停駛，請以月台看板為準。": "열차 운행 중단을 뜻하지 않아요. 승강장 안내를 확인하세요.",
    "這個帳號目前沒有可恢復的通行證資格。": "이 계정에는 복원할 수 있는 패스 구매 내역이 없어요",
