    "跟車配樂：音樂跟著你在看的那班車與當下時間換情境": "열차 배경 음악: 보고 있는 열차와 시간대에 맞춰 분위기가 바뀌어요",
    "音樂跟著你在看的那班車走——車開到哪、現在幾點就換到對應的情境。": "보고 있는 열차의 위치와 시간대에 맞춰 음악 분위기가 바뀌어요",
