    "想固定聽某一種就直接點家族或情境，會一直停在那裡": "같은 분위기를 계속 듣고 싶으면 음악 그룹이나 분위기를 직접 고르세요",
    "要換回自動，再點一次「跟著列車」": "자동으로 돌아가려면 열차에 맞추기를 다시 누르세요",
    "換情境只發生在一首播完之後，不會把正在聽的曲子切掉；短暫經過一個地區也不會馬上換。通行證到期會自動退回免費的隨機播放，你選過的情境會留著。": "곡이 끝난 뒤에 분위기가 바뀌므로 재생 중인 곡은 끊기지 않아요. 지역을 잠깐 지나는 것만으로는 바뀌지 않아요. 패스가 만료되면 무료 무작위 재생으로 돌아가지만 선택한 분위기는 저장돼요.",
