    "只有開啟這個選項才會上傳最新一筆座標；App 留在前景時更新，收起或鎖屏後立即暫停。": "이 옵션을 켜야 최신 위치 1건이 업로드돼요. 앱이 화면에 열려 있을 때만 갱신하며, 백그라운드로 보내거나 화면을 잠그면 즉시 중단돼요.",
    "只有開啟這個選項才會上傳最新一筆座標；頁面留在前景時更新，切到背景後暫停傳送。": "이 옵션을 켜야 최신 위치 1건이 업로드돼요. 이 페이지가 화면에 열려 있을 때만 갱신하며, 백그라운드로 보내면 전송을 중단해요.",
    "正在分享": "공유 중",
    "手機定位已停止，但伺服器尚未確認刪除；請再按一次「停止分享並刪除」。": "휴대폰 위치 확인은 중단했지만 서버 삭제는 아직 확인되지 않았어요. 공유 중단 및 삭제를 다시 눌러 주세요.",
