    "放大地圖即可看見立體列車。完整編組依車型或路線標準；缺少當班資料時顯示三節示意。起伏為地表顯示，非實測軌道高程。透視顯示同時管建築與地下列車，切到實體就看得到地下列車原本的顏色。": "지도를 확대하면 3D 열차를 볼 수 있어요. 전체 편성은 차종 또는 노선 표준을 따르며, 실제 정보가 없으면 3량 예시로 표시해요. 지형은 지표면 표현이며 실측 선로 높이가 아니에요. 투과 보기는 건물과 지하 열차에 함께 적용돼요. 불투명으로 바꾸면 지하 열차의 원래 색을 볼 수 있어요.",
