    "（其他系統部分路線為班距推算）": "(다른 시스템의 일부 노선은 배차간격으로 추정)",
    "中和新蘆線": "중허신루선",
    "新北捷運": "신베이 MRT",
    "桃園捷運": "타오위안 MRT",
    "台北捷運、桃園機捷、新北捷運（環狀・淡海・安坑・三鶯）、台中捷運與高雄捷運（含輕軌）同框運行，營運時段依官方即時資訊校正（台北捷運九線的列車位置與車站倒數都是官方逐班即時；三鶯線與台中捷運為班距推算）— 可在上方勾選要同時顯示的系統。": "타이베이, 타오위안 공항, 신베이(순환 · 단하이 · 안컹 · 싼잉), 타이중, 가오슝(경전철 포함)의 MRT를 함께 볼 수 있어요. 운행 중 공식 실시간 정보로 보정하며, 타이베이 MRT 9개 노선의 위치와 도착 카운트다운은 공식 열차별 실시간 정보예요. 싼잉선과 타이중 MRT는 배차간격으로 추정해요. 위에서 함께 표시할 시스템을 선택하세요.",
    "台鐵、高鐵與阿里山林鐵皆依真實時刻表運行（台鐵回到現在時刻自動套用即時誤點；林鐵依官方公告時刻表，無即時資訊）— 點列車跟隨、點車站看班次，或按地圖角落「探」看今日亮點。": "대만철도 · 고속철도 · 아리산 삼림철도는 실제 시간표에 따라 운행해요. 현재 시간에는 대만철도 실시간 지연을 반영하고, 삼림철도는 공식 시간표만 사용해요. 열차를 눌러 따라가고, 역을 눌러 도착 안내를 보거나, 지도 모서리의 탐색 버튼에서 오늘의 하이라이트를 찾아보세요.",
    "台中捷運與高雄捷運同框，高捷與輕軌營運時段依官方到站看板校正（台中捷運為班距推算）— 可在上方勾選要同時顯示的系統。": "타이중 · 가오슝 MRT를 함께 볼 수 있어요. 가오슝 MRT와 경전철은 운행 중 공식 도착 안내로 보정하며, 타이중 MRT는 배차간격으로 추정해요. 위에서 함께 표시할 시스템을 선택하세요.",
    "跟隨鎖定中：地圖固定列車置中——點擊或直接拖曳地圖解鎖，可自由瀏覽": "따라가기 잠금 중: 열차를 지도 중앙에 고정해요. 누르거나 지도를 드래그하면 잠금이 풀려 자유롭게 둘러볼 수 있어요.",
    "自由瀏覽中：點擊回到列車，恢復置中跟隨": "자유롭게 둘러보는 중: 누르면 열차로 돌아가 중앙에서 따라가요",
