    "為避免手機卡頓，這些地點不逐筆顯示；勾選後會全部納入。": "휴대폰 성능을 위해 하나씩 표시하지 않아요. 선택하면 모두 포함돼요.",
    "查看": "보기",
    "其餘 {n} 筆預設不匯入；可用上方選項一次納入。": "나머지 {n}개는 기본적으로 제외돼요. 위의 옵션으로 한 번에 포함할 수 있어요.",
