    "另有 {n} 筆未列出；可先完成這批再重新匯入。": "표시되지 않은 {n}개가 더 있어요. 이번 목록을 처리한 뒤 다시 가져올 수 있어요.",
    "這份檔案沒有可匯入的台灣地點。": "이 파일에는 가져올 수 있는 대만 장소가 없어요",
    "請在地圖上點「{name}」的正確位置；點下後會回到確認畫面": "지도에서 {name}의 정확한 위치를 눌러 주세요. 누르면 확인 화면으로 돌아가요.",
    "正在裝置內讀取與解析…": "기기 안에서 파일을 읽고 분석하는 중…",
    "已讀取 {n} 個清單檔案，請確認後再匯入。": "목록 파일 {n}개를 읽었어요. 확인 후 가져오세요.",
