    "，更新 {n} 個既有地點": ", 기존 장소 {n}개 수정",
    "；{n} 個因收藏已滿略過": "; 즐겨찾기가 가득 차 {n}개 제외",
    "軌島使用者": "Rail Island 사용자",
    "登入與同步目前無法使用。": "현재 로그인과 동기화를 사용할 수 없어요",
    "正在讀取登入狀態…": "로그인 상태 확인 중…",
    "登入後會同步「最愛地點、最愛車站、最愛列車、完乘紀錄」。主題、音量與省電等裝置偏好不會同步。若這台裝置沒有記著別的帳號，首次登入時會把裝置上的訪客資料併入帳號；若這台裝置還記著上一個登入的別的帳號，訪客資料不會自動併入，但仍留在裝置上，不會遺失。": "로그인하면 즐겨찾는 장소 · 역 · 열차와 완주 기록을 동기화해요. 테마 · 음량 · 절전 같은 기기 설정은 동기화하지 않아요. 이 기기에 다른 계정 기록이 없으면 첫 로그인 때 게스트 기록을 계정에 합쳐요. 이전에 다른 계정이 로그인한 기록이 있으면 자동으로 합치지 않지만 게스트 기록은 기기에 그대로 남아요.",
    "使用 Google 登入": "Google로 로그인",
    "使用 Apple 登入": "Apple로 로그인",
    "先看看軌島通行證有什麼": "먼저 Rail Island 패스 살펴보기",
    "沒有跳出 Google 帳號選擇畫面嗎？可以改用另一種方式登入。": "Google 계정 선택 화면이 열리지 않나요? 다른 로그인 방법을 사용해 보세요.",
    "改用另一種方式登入": "다른 방법으로 로그인",
    "這台裝置的 Google 登入試了兩種方式都不成功。可以改用上面的「使用 Apple 登入」，它不需要 Google 服務。": "이 기기에서 두 가지 Google 로그인 방법이 모두 실패했어요. 위의 ‘Apple로 로그인’을 이용할 수 있어요. 이 방법은 Google 서비스가 필요하지 않아요.",
    "Google 登入只用於軌島帳號，不會因此取得 Google Maps 已儲存清單；清單匯入仍需使用 Google Takeout。": "Google 로그인은 Rail Island 계정에만 사용되며 Google Maps 저장 목록 접근 권한은 얻지 않아요. 목록은 Google Takeout으로 별도 가져와야 해요.",
