    "併入失敗：這台裝置的儲存空間不足": "합치기 실패: 기기 저장 공간이 부족해요",
    "登出會先完成最後同步，再把畫面切回訪客狀態。你的收藏留在這台裝置上，同一個帳號登入就會回來；換別人登入看不到，也不會被合併。要一併清除這台裝置上的收藏，請用下方的「刪除帳號與同步資料」。": "로그아웃 전에 마지막 동기화를 마친 뒤 게스트 화면으로 돌아가요. 즐겨찾기는 기기에 남고 같은 계정으로 로그인하면 다시 보여요. 다른 계정에서는 보이지 않으며 합쳐지지도 않아요. 기기의 즐겨찾기도 지우려면 아래의 계정 및 동기화 데이터 삭제를 사용하세요.",
    "軌島帳號與同步資料已刪除": "Rail Island 계정과 동기화 데이터를 삭제했어요",
