    "我的車・準點": "내 열차 · 정시 운행",
    "收藏台鐵列車後，這裡會集中列出它們近 30 天的準點表現，通行證訂閱者可完整比較——跟隨列車時點資訊卡的收藏鈕即可收藏。": "즐겨찾는 대만철도 열차의 최근 30일 정시 운행 현황을 모아 보여 줘요. 패스 구독자는 전체 비교를 볼 수 있어요. 따라가는 중에 열차 카드의 즐겨찾기 버튼을 눌러 추가하세요.",
