    "從已入庫的車挑一款，取個五字內的名字，排好路線和時間，它就住進這一股。": "수집한 차량 중 하나를 고르고 5자 이내로 이름을 지은 뒤 노선과 시간을 정하면 이 선로에 들어와요.",
    "車庫裡還沒有可以自己排班的車。先到車庫看看怎麼收集。": "아직 직접 배차할 수 있는 차량이 없어요. 차고에서 수집 방법을 확인해 보세요.",
