    "路線資料有變動，這列車要重新排才能上路。": "노선 자료가 바뀌었어요. 다시 배차해야 운행할 수 있어요.",
    "這是示範車。開通行證後可以排滿 6 股，每一列都有自己的首航日與里程。": "시범 열차예요. 패스가 있으면 선로 6개를 모두 채울 수 있고, 열차마다 첫 운행일과 거리가 기록돼요.",
    "通行證到期了。車隊都還在，開通行證後回到地圖上跑。": "패스가 만료됐어요. 차량은 그대로 있고 패스를 켜면 다시 지도에서 달려요.",
    "地圖時鐘不在現在，回到現在才能親手發車。": "지도 시계가 현재가 아니에요. 현재로 돌아가야 직접 출발시킬 수 있어요.",
