    "你排的 {name} 要重新排：起站或訖站已經不在站點資料裡": "{name} 다시 배차 필요: 역 자료에서 출발역 또는 도착역을 찾을 수 없어요",
    "重新排": "다시 배차",
    "你排的 {name} 要重新排：路線資料有變動": "{name} 다시 배차 필요: 노선 자료가 바뀌었어요",
