    "這款車之前就換過了，這次沒有扣除。": "이 차량은 이미 교환했어요. 이번에는 포인트가 차감되지 않았어요.",
    "另一款車的兌換還沒確認，請先處理那一款。": "다른 차량의 교환 결과가 아직 확인되지 않았어요. 먼저 그 차량을 처리하세요.",
