    "高雄輕軌駁二大義站 · 微縮印象": "가오슝 경전철 보얼다이역 · 미니어처 풍경",
    "高鐵新竹站": "고속철도 신주역",
    "台灣高鐵・新竹站": "대만 고속철도 · 신주역",
    "新竹站全景": "신주역 전경",
    "風城晴日": "바람의 도시, 맑은 낮",
    "竹塹夕照": "신주의 노을",
    "風帆夜色": "돛 모양 지붕의 밤 불빛",
    "正在把小車送上高鐵新竹站…": "작은 열차를 고속철도 신주역으로 올리는 중…",
    "台灣高鐵新竹站 · 微縮印象": "대만 고속철도 신주역 · 미니어처 풍경",
    "「觀看」→「列車」新增誤點外框：台鐵車牌與圓點外加一圈，顏色照現在誤點幾分鐘由綠轉紅，車種色保留": "‘보기’ → ‘열차’에 지연 테두리를 추가했어요. 대만철도 열차 번호판과 점에 현재 지연 시간에 따라 초록에서 빨강으로 바뀌는 테두리가 생겨요",
    "平交道補上鶯歌到鳳鳴之間的尖山埔路，全台共 347 處（謝謝網友回報）": "잉거와 펑밍 사이의 젠산푸로 건널목을 추가해 대만 전역 347곳이 됐어요. 제보해 주셔서 감사해요",
    "通行證的自製列車擴成 6 列，住進新的 3D 扇形車庫「軌島機務段」：每列有成就、頭牌和車牌框，還能親手發車；登入同帳號，車隊跨裝置同步（目前網站版）": "패스 전용 나만의 열차가 최대 6편성으로 늘고 새 3D 부채꼴 차고 ‘Rail Island 차량기지’에 들어갔어요. 열차마다 업적, 헤드마크, 번호판 테두리가 있고 직접 출발도 할 수 있어요. 같은 계정으로 로그인하면 기기 간에 동기화돼요(지금은 웹사이트만)",
    "捷運路線圖頁拿掉已結束的設計展疏運附註，頁面日期和時刻表抓取日也改成實際資料日期": "노선도 페이지에서 끝난 디자인 엑스포 수송 안내를 없애고, 페이지 날짜와 시간표 수집일도 실제 데이터에 맞췄어요",
    "進車庫會隨機放背景音樂，離開就收掉；頂列和場景頁多了音樂鈕，關過音樂就不自動放": "차고에 들어가면 배경 음악이 무작위로 나오고 나가면 멈춰요. 상단 바와 풍경 페이지의 음악 버튼으로 끄면 자동으로 나오지 않아요",
    "區間車列車卡新增車型推估：依鐵道維基館運用表標出 EMU500／600／700／800／900，實際以當日調度為準": "구간열차 카드에 추정 차종을 추가했어요. 철도 위키 운용표를 바탕으로 EMU500/600/700/800/900을 표시하며, 실제 배차는 다를 수 있어요",
    "「觀看」→「列車」新增「顯示虛構專列」開關，關掉後地圖、看板和查詢只留真實列車": "‘보기’ → ‘열차’에 ‘가상 특별열차 표시’ 스위치를 추가했어요. 끄면 지도, 전광판, 검색에 실제 열차만 남아요",
    "車庫新增 11 座台鐵特色車站場景：新竹、台南、台中舊站、嘉義、保安、集集、冬山、高雄、大山、勝興、台北地下月台": "차고에 대만철도 특색 역 풍경 11곳을 추가했어요. 신주, 타이난, 타이중 옛 역, 자이, 바오안, 지지, 둥산, 가오슝, 다산, 성싱, 타이베이 지하 승강장",
    "車庫的點數現在寫明存在哪個帳號；換了登入方式會提醒你原本的帳號，刪帳號前也會列出會一起刪掉的點數和場景": "차고의 포인트가 어느 계정에 저장되는지 표시돼요. 로그인 방법을 바꾸면 원래 계정을 알려 주고, 계정을 삭제하기 전에 함께 지워지는 포인트와 풍경도 보여 줘요",
    "EMU3000 新自強號的 3D 車模重新製作，外型更接近實車": "EMU3000 3D 모델을 새로 만들어 실제 열차에 더 가까워졌어요",
    "Q 版列車從側面看時，並行的列車不再互相穿過": "귀엽게 보기에서 옆에서 볼 때 나란히 달리는 열차가 서로 통과해 보이지 않아요",
    "台中捷運綠線首班車改回 06:00：交通部 TDX 資料已改回原本時刻，11/8 提早到 05:30 的那版不再採用，末班不變": "타이중 MRT 녹색선 첫차를 06:00으로 되돌렸어요. 교통부 TDX 자료가 원래 시각으로 돌아가서 11/8의 05:30 버전은 더 이상 쓰지 않아요(막차는 그대로예요)",
    "車庫新增 12 款車：EMU200、DR2800、S400、EMU400、0 系新幹線、總統花車等，各用 150 島民點數兌換": "차고에 12종을 추가했어요(EMU200, DR2800, S400, EMU400, 신칸센 0계, 귀빈 객차 등). 각각 섬주민 포인트 150점으로 교환해요",
    "車庫場景與車款加上介紹，車款詳情多了「車款檔案」，列車卡 8 個車種各補一則小知識": "차고 장면과 차량에 소개를 추가했어요. 차량 상세에 '차량 정보'가 생기고, 열차 카드는 8개 차종에 상식을 하나씩 더했어요",
    "CK124、CT273、DT668 三款蒸汽機車的 3D 車模照實車重新製作": "증기기관차 CK124, CT273, DT668의 3D 모델을 실제 열차에 가깝게 새로 만들었어요",
    "車庫裡的客車款跑起來會配上機車頭，復興號、莒光號不再沒有車頭": "차고의 객차 모델은 이제 기관차가 끌고 달려요. 푸싱호와 쥐광호 맨 앞에 기관차가 붙어요",
    "22 款列車的 3D 車模對照實車照片修正，海風號、山嵐號、R200 改動最大": "열차 22종의 3D 모델을 실제 사진과 비교해 고쳤어요. 하이펑호, 산란호, R200이 가장 크게 바뀌었어요",
    "車庫場景頁的時段鈕、標題和車款選單放不下時改成換行，Safari 點車款也換得到車": "차고 풍경 페이지의 시간대 버튼, 제목, 차종 메뉴가 넘치면 줄바꿈되고, Safari에서 차종을 골라도 바뀌지 않던 문제도 고쳤어요",
    "手機橫放時，車庫的機務段入口排到展示台下面，第一屏看得到完整車模": "휴대폰을 가로로 두면 차고의 차량기지 입구가 전시대 아래로 옮겨져 첫 화면에서 차량 전체가 보여요",
    "車庫音樂改到場景頁才放，只放慢版鋼琴，車跑起來還有鐵軌聲；車庫首頁不出聲，音符鈕留在場景頁": "차고 음악은 이제 장면 화면에서만 나와요. 잔잔한 피아노에 열차가 달리면 철길 소리가 더해져요. 차고 첫 화면은 조용하고, 음표 버튼은 장면 화면에 있어요",
    "新增韓文捷運路線圖：台北、桃園、新北、台中、高雄各線的車站、轉乘與首末班車都有韓文版": "한국어 MRT 노선도를 추가했어요. 타이베이 · 타오위안 · 신베이 · 타이중 · 가오슝 각 노선의 역, 환승, 첫차 · 막차를 한국어로 볼 수 있어요",
    "新增韓文網頁：30 個車站的時刻表與轉乘，還有介紹、準確度、資料來源頁都有韓文版": "한국어 웹페이지를 추가했어요. 역 30곳의 시간표와 환승, 소개 · 정확도 · 데이터 출처 페이지를 한국어로 볼 수 있어요",
