    "正在把小車送進台北車站…": "작은 열차를 타이베이역으로 옮기는 중…",
    "台北車站 · 微縮印象": "타이베이역 · 미니어처 풍경",
    "介面新增韓文：語言列多了「한국어」，地圖、使用說明、介紹頁與條款都能切成韓文": "한국어를 추가했어요. 언어 줄에서 ‘한국어’를 고르면 지도 · 이용 안내 · 소개 페이지 · 약관을 한국어로 볼 수 있어요",
    "介面可以切成繁中、英文、日文、韓文；「更多」裡也收著台南地面鐵道的兩場歷史重播。": "화면 언어를 번체 중국어 · 영어 · 일본어 · 한국어로 바꿀 수 있어요. ‘더보기’에는 타이난 지상 철도 역사 다시 보기 두 편도 있어요.",
    "「語言」那一列點「繁中」「EN」「日本語」「한국어」其中一個，介面文字就換過去": "‘언어’ 줄에서 원하는 언어 버튼을 누르면 화면 글자가 바로 바뀌어요",
    "快轉 30 倍以上不再限制地圖放大，放慢之後也不會卡在放不到最大": "30배속 이상에서도 지도 확대 제한을 없앴고, 속도를 줄인 뒤 최대로 확대되지 않던 문제도 수정했어요",
    "換列車": "열차 바꾸기",
    "地圖上的立體列車改成放大的 Q 版三節，遠看也看得清楚；可在「觀看」→「列車」→「列車大小」切回": "지도의 3D 열차를 크게 키운 3량 ‘귀엽게 보기’로 바꿨어요. 멀리서도 잘 보이고 ‘보기’ → ‘열차’ → ‘열차 크기’에서 되돌릴 수 있어요",
    "有軌島通行證的人，App 校正懸賞錄程的島民點數多 50%，加成不算進每天 500 點上限": "Rail Island 패스가 있으면 앱 보정 미션 기록의 섬주민 포인트를 50% 더 받아요. 추가분은 하루 500포인트 한도에 포함되지 않아요",
    "車庫畫面多了「換列車」鈕，全畫面和場景頁也能直接換車": "차고에 ‘열차 바꾸기’ 버튼을 추가했어요. 전체 화면과 풍경 페이지에서도 바로 바꿀 수 있어요",
