    "另一處": "다른 곳",
    "最多 {n} 班同時誤點": "최대 {n}편 동시 지연",
    "比最早卡住晚了 {d}。誤點會一路累積，大事故的尖峰通常晚 4 小時左右": "시작 {d} 뒤예요. 지연은 갈수록 쌓여서 큰 사고가 난 날은 보통 4시간쯤 뒤에 정점이 와요",
    "全台誤點 5 分以上的車，這天這時候最多": "이날 전국에서 5분 이상 늦은 열차가 가장 많았던 때예요",
    "{a}—{b} 多出 {inc} 分": "{a}–{b}에서 {inc}분 지연",
    "{no} 次，這天最明顯的一段": "{no}편, 이날 가장 눈에 띈 구간이에요",
    "小狀況": "작은 지연",
    "半夜還有 {n} 班誤點": "자정에도 {n}편 지연",
    "到收班都還沒回到準點。大事故的日子有六成多會這樣，平常不到一成": "막차까지 정시로 돌아오지 못했어요. 큰 사고가 난 날은 60%가 넘게 이렇고, 평소에는 10%도 안 돼요",
    "到收班都還沒回到準點": "막차까지 정시로 돌아오지 못했어요",
    "收尾": "막차",
    "這天沒有大事故，{t} 最多 {n} 班同時誤點": "이날은 큰 사고가 없었어요. {t}에 최대 {n}편이 동시에 지연됐어요",
